def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each 3-color marker is a seed for the same 3x3 pattern. The seed's
    # color is at the upper-left; copy the pattern one step up and left.
    pattern = [[1, 1, 0], [0, 4, 0], [0, 1, 5], [4, 4, 7], [0, 7, 7]]
    # Demos show a five-row, three-column motif rooted at each 3 marker.
    # Pattern entries are placed starting two rows above and one column left.
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                for dr, row in enumerate(pattern):
                    for dc, v in enumerate(row):
                        rr, cc = r - 2 + dr, c - 1 + dc
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] in (7, 3):
                            out[rr][cc] = v
    return out

